$docs = @{ "zoom" = "01-eula-terms-of-service-zoom" "deepfake" = "02-eula-explainable-deepfake-detection-challenge-2026" "adobe" = "03-reader-eula-adobe" "steam" = "04-steam-subscriber-agreement" "spotify" = "05-terms-and-conditions-of-use-spotify" "windows11" = "07-useterms-oem-windows-11-english" } foreach ($key in $docs.Keys) { $slug = $docs[$key] $studyPath = if ($slug -like "0[123]-*") { "study-1" } else { "study-2" } $src = "..\their-repo\public\precomputed_data\$studyPath\documents\$slug\assets" New-Item -ItemType Directory -Force -Path "$key\comics" | Out-Null New-Item -ItemType Directory -Force -Path "$key\videos" | Out-Null Copy-Item "$src\comics\*" -Destination "$key\comics\" -ErrorAction SilentlyContinue Copy-Item "$src\videos\*" -Destination "$key\videos\" -ErrorAction SilentlyContinue Write-Host "Copied $key from $slug" }